export type Method<P, R> = { params: P, result: R, };
export type ResponseType = "response";
export type WireRequest<M, P> = { id: string, method: M, params?: P, expectInstanceId?: string, expectSessionId?: string, };
export type WireResponse<R> = { type: ResponseType, id: string, ok: True, result: R, } | { type: ResponseType, id: string | null, ok: False, error: ProtocolError, };
export type ServerMessage = Response | EventMessage;
export type True = true;
export type False = false;
export type Empty = Record<string, never>;
export type ParamsOf<M extends RcMethod> = RcMethods[M]["params"];
export type ResultOf<M extends RcMethod> = RcMethods[M]["result"];
export type Request<M extends RcMethod = RcMethod> = WireRequest<M,ParamsOf<M>>;
export type Response<M extends RcMethod = RcMethod> = WireResponse<ResultOf<M>>;
